.studio{display:grid;grid-template-columns:190px minmax(0,1fr);gap:24px;margin-top:24px}.studio aside{background:#172a40;color:white;border-radius:12px;padding:18px;align-self:start;position:sticky;top:16px}.studio aside button{display:block;width:100%;text-align:left;background:transparent;border:0;color:white;padding:10px;margin:2px 0;border-radius:6px}.studio aside .selected{background:#176be0}.workspace{min-width:0;background:#f9fbfd;border:1px solid #d4dce4;border-radius:12px;padding:20px}header,.toolbar,.skin-cell,.hair-options,.previews{display:flex;align-items:center;gap:8px;flex-wrap:wrap}button,input,select{padding:7px;font:inherit;border:1px solid #bbc8d6;border-radius:5px;margin:3px}button{cursor:pointer}button:disabled{opacity:.45;cursor:default}.primary{background:#176be0;color:white;border:0}.notice{padding:10px;background:#fff0ca}.error{color:#a32121}.table-scroll{overflow:auto}table{border-collapse:collapse;width:100%}td,th{border-bottom:1px solid #d4dce4;padding:6px;text-align:left;vertical-align:top}th{background:#edf3f9}.number{width:50px}.name{width:96px}.modified{background:#fff8df}details label{display:block;white-space:nowrap}.hair{display:flex;align-items:center;gap:5px}.skin-color{width:20px;height:20px;padding:0;border:0;flex:none}.skin-color::-webkit-color-swatch-wrapper{padding:0}.skin-color::-webkit-color-swatch{border:0}.palette-editor{display:flex;flex-wrap:wrap;gap:12px}.palette-editor label{display:flex;align-items:center;gap:4px}.palette-editor input{width:44px;height:36px;padding:2px}.hair-dialog{position:fixed;inset:20%;z-index:20;box-shadow:0 0 0 100vmax #0008;border:0;border-radius:12px}.waveform{width:100%;max-width:700px;background:#edf3f9}.pitch{display:block;width:300px;max-width:100%;margin:16px 0}code{overflow-wrap:anywhere;font-size:11px}audio{display:block;margin:12px 0}figure{margin:12px}@media(max-width:800px){.studio{grid-template-columns:1fr}.studio aside{position:static}.studio aside button{display:inline-block;width:auto}.workspace{padding:10px}}
